from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    nxt = [{}]
    out = [False]
    for word in banned:
        u = 0
        for ch in word:
            v = nxt[u].get(ch)
            if v is None:
                v = len(nxt)
                nxt[u][ch] = v
                nxt.append({})
                out.append(False)
            u = v
        out[u] = True

    nodes = len(nxt)
    fail = [0] * nodes
    go = [{} for _ in range(nodes)]
    q = deque()

    for ch in alphabet:
        v = nxt[0].get(ch)
        if v is None:
            go[0][ch] = 0
        else:
            go[0][ch] = v
            q.append(v)

    while q:
        u = q.popleft()
        if out[fail[u]]:
            out[u] = True
        for ch in alphabet:
            v = nxt[u].get(ch)
            if v is None:
                go[u][ch] = go[fail[u]][ch]
            else:
                fail[v] = go[fail[u]][ch]
                go[u][ch] = v
                q.append(v)

    id_of = {}
    for u in range(nodes):
        if not out[u]:
            id_of[u] = len(id_of)
    m = len(id_of)
    mat = [[0] * m for _ in range(m)]
    for u, i in id_of.items():
        for ch in alphabet:
            j = id_of.get(go[u][ch])
            if j is not None:
                mat[i][j] += 1

    def mul(a, b):
        c = [[0] * m for _ in range(m)]
        for i in range(m):
            ai = a[i]
            ci = c[i]
            for k in range(m):
                aik = ai[k]
                if aik:
                    bk = b[k]
                    for j in range(m):
                        ci[j] = (ci[j] + aik * bk[j]) % MOD
        return c

    ans = [[1 if i == j else 0 for j in range(m)] for i in range(m)]
    base = mat
    e = n
    while e:
        if e & 1:
            ans = mul(ans, base)
        base = mul(base, base)
        e >>= 1
    return sum(ans[0]) % MOD
